<?php $__env->startSection('breadcrumb','Roles & permissions'); ?>
<?php $__env->startSection('content'); ?>
<div class="page-heading"><div><div class="eyebrow">ACCESS CONTROL</div><h1>Roles & permissions</h1><p>Configure module-level access using least-privilege assignments.</p></div></div>
<div class="alert alert-info border-0"><i class="bi bi-info-circle me-2"></i>The Super Administrator role always retains unrestricted access. Assign only the permissions needed for each operational role.</div>
<div class="row g-3"><?php $__currentLoopData = $roles; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $role): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><div class="col-12"><div class="panel"><form method="POST" action="<?php echo e(route('admin.roles.update',$role)); ?>"><?php echo csrf_field(); ?> <?php echo method_field('PUT'); ?><div class="panel-header role-panel-head"><div><h2><?php echo e($role->name); ?></h2><p><?php echo e($role->description ?: 'No role description provided.'); ?> <span class="role-slug"><?php echo e($role->slug); ?></span></p></div><div class="d-flex align-items-center gap-2"><span class="small-muted"><?php echo e($role->permissions->count()); ?> permissions</span><?php if($role->slug==='super-admin'): ?><span class="status-pill active">Full access</span><?php else: ?><button class="btn btn-sm btn-primary">Save permissions</button><?php endif; ?></div></div>
<?php if($role->slug!=='super-admin'): ?><div class="permission-grid"><?php $__currentLoopData = $permissions; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $module=>$items): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><div class="permission-group"><div class="permission-group-title"><?php echo e(ucfirst($module)); ?></div><?php $__currentLoopData = $items; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $permission): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><label class="permission-item"><input class="form-check-input" type="checkbox" name="permissions[]" value="<?php echo e($permission->id); ?>" <?php if($role->permissions->contains('id',$permission->id)): echo 'checked'; endif; ?>><span><?php echo e($permission->label); ?></span></label><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></div><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></div><?php else: ?><div class="role-superadmin-note">This role bypasses permission checks by design. Keep its membership strictly limited.</div><?php endif; ?>
</form></div></div><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></div>
<?php $__env->stopSection(); ?>

